from pathlib import Path
import ast, py_compile, shutil
from datetime import datetime
APP=Path(__file__).with_name("clinique_mughulungu.py")
if not APP.exists(): raise SystemExit(f"Fichier introuvable: {APP}")
source=APP.read_text(encoding="utf-8")
tree=ast.parse(source)
node=None
for n in tree.body:
    if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=="LOGIN" for t in n.targets): node=n; break
if node is None: raise SystemExit("Affectation LOGIN introuvable; aucune modification effectuée.")
