lines=source.splitlines(keepends=True)
lines[node.lineno-1:node.end_lineno]=["LOGIN = "+repr(LOGIN_HTML)+"\n"]
candidate="".join(lines)
ast.parse(candidate)
backup=APP.with_name(APP.stem+".before-page-connexion-"+datetime.now().strftime("%Y%m%d-%H%M%S")+APP.suffix)
shutil.copy2(APP,backup)
APP.write_text(candidate,encoding="utf-8")
py_compile.compile(str(APP),doraise=True)
print("PAGE DE CONNEXION APPLIQUÉE — sauvegarde:",backup)
print("Validation Python: OK")
print("PostgreSQL: aucune modification")
